//! The draft curriculum `data/curriculum/g9-ct9-480.draft.v1.json` against the Appendix A seed.
//!
//! The draft is generated by `scripts/build_curriculum.py` from `docs/curriculum/weeks/`; the
//! Python builder and `scripts/check_curriculum_seed.py` check it on the authoring side. These
//! tests check it with the application's own parser, validator and diff, so the claims in
//! `docs/curriculum/design.md` hold in the code that imports and promotes it:
//!
//! * the draft is valid, `PROPOSED_SEED` and non-authoritative;
//! * it keeps the seed's structure and wording: an enrichment, not a replacement;
//! * `reconcile(seed, draft)` is a reviewable diff limited to the enrichment fields;
//! * promotion stays blocked until a reconciliation block bound to that exact diff exists.
//!
//! Nothing here approves anything: the operator's approval is a command-level step
//! (`curriculum.promote`), never decided by a test.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use g9_curriculum::*;
use g9_domain::{ManifestProvenance, UtcMillis};
use pretty_assertions::assert_eq;
use std::collections::BTreeSet;

const SEED: &str = include_str!("../../../data/curriculum/g9-ct9-480.seed.v0.json");
const DRAFT: &str = include_str!("../../../data/curriculum/g9-ct9-480.draft.v1.json");

/// The separator between an Appendix A wording and the text the draft adds to it.
const ADDED: &str = " — ";

fn seed() -> Manifest {
    parse_manifest(SEED).expect("the seed parses")
}

fn draft() -> Manifest {
    parse_manifest(DRAFT).expect("the draft parses")
}

/// The only per-day fields in which the draft may differ from the seed.
fn is_enrichment_field(field: &str) -> bool {
    field == "evidence_artifact"
        || field == "resources"
        || (0..3).any(|i| {
            field == format!("objectives[{i}].text")
                || field == format!("objectives[{i}].competency_ids")
        })
}

fn reconciled(original: &ReconciliationReport, candidate: &Manifest) -> Manifest {
    let mut m = candidate.clone();
    m.provenance = ManifestProvenance::ReconciledCandidate;
    m.version = "1.0.0-rc1".to_string();
    m.reconciliation = Some(Reconciliation {
        original_checksum: original.original_checksum.as_str().to_string(),
        diff_checksum: original.diff_checksum.as_str().to_string(),
        approved_by: "operator".to_string(),
        approved_at: UtcMillis::from_millis(1_763_000_000_000),
    });
    m
}

#[test]
fn the_draft_is_valid_proposed_and_not_authoritative() {
    let (m, report) = load_manifest(DRAFT).expect("the draft validates");
    assert_eq!(report.errors, Vec::<ManifestError>::new());
    assert_eq!(report.violations, vec![]);
    assert_eq!(m.provenance, ManifestProvenance::ProposedSeed);
    assert_eq!(m.version, "1.0.0-draft1");
    assert_eq!(m.curriculum_id, seed().curriculum_id);
    assert!(
        m.reconciliation.is_none(),
        "a draft carries no reconciliation block: nobody has reviewed its diff"
    );
    assert!(
        m.provenance_note
            .as_deref()
            .is_some_and(|n| n.contains("PROPOSED")),
        "the note states that the content is proposed"
    );

    // Same arithmetic as the seed: 12 weeks, 72 days, 216 objectives, 28,800 minutes.
    let inv = g9_domain::CURRICULUM_INVARIANTS;
    assert_eq!(report.counts.weeks, inv.weeks);
    assert_eq!(report.counts.days, inv.total_days);
    assert_eq!(report.counts.objectives, inv.total_objectives);
    assert_eq!(report.counts.total_minutes, inv.total_minutes);

    // A plan derived from it is labelled, never authoritative.
    let plan = daily_plan(&m, 1, 1).unwrap();
    assert_eq!(plan.provenance, ManifestProvenance::ProposedSeed);
    assert!(!plan.authoritative);
}

#[test]
fn the_draft_keeps_the_seed_structure_and_wording() {
    let (s, d) = (seed(), draft());
    assert_eq!(
        (&s.curriculum_id, &s.name, &s.structure),
        (&d.curriculum_id, &d.name, &d.structure)
    );
    assert_eq!(s.weekday_blocks, d.weekday_blocks);
    assert_eq!(s.saturday_blocks, d.saturday_blocks);
    assert_eq!(s.weeks.len(), d.weeks.len());

    for (sw, dw) in s.weeks.iter().zip(&d.weeks) {
        assert_eq!(
            (sw.week_number, &sw.title),
            (dw.week_number, &dw.title),
            "week titles are the owner's and are not renamed"
        );
        assert_eq!(sw.days.len(), dw.days.len());
    }

    for ((_, sd), (_, dd)) in s.days().zip(d.days()) {
        let id = &sd.day_id;
        assert_eq!(id, &dd.day_id);
        assert_eq!(sd.day_of_week, dd.day_of_week, "{id}");
        assert_eq!(sd.planned_minutes, dd.planned_minutes, "{id}");
        assert_eq!(sd.is_assessment_day, dd.is_assessment_day, "{id}");
        assert_eq!(sd.blocks, dd.blocks, "{id}");

        assert_eq!(sd.objectives.len(), dd.objectives.len(), "{id}");
        for (so, dobj) in sd.objectives.iter().zip(&dd.objectives) {
            assert_eq!((so.seq, &so.objective_id), (dobj.seq, &dobj.objective_id));
            assert!(
                dobj.text.starts_with(&format!("{}{ADDED}", so.text)),
                "{}: the Appendix A wording '{}' must start the text",
                dobj.objective_id,
                so.text
            );
            assert!(
                dobj.text.chars().count() > so.text.chars().count() + ADDED.chars().count(),
                "{}: a success criterion follows the wording",
                dobj.objective_id
            );
            assert!(
                (1..=3).contains(&dobj.competency_ids.len()),
                "{}: one to three competencies",
                dobj.objective_id
            );
        }
        assert!(
            dd.evidence_artifact
                .starts_with(&format!("{}{ADDED}", sd.evidence_artifact)),
            "{id}: the Appendix A artifact name must start the hand-in"
        );

        // Resources: an external, versioned, licence-noted source, and the day's own sheet.
        assert!(
            sd.resources.is_empty(),
            "{id}: the seed carries no resources"
        );
        let external: Vec<_> = dd
            .resources
            .iter()
            .filter(|r| r.kind == ResourceKind::External)
            .collect();
        assert!(!external.is_empty(), "{id}: at least one external resource");
        for r in &external {
            assert!(r.reference.starts_with("https://"), "{id}: {}", r.reference);
            assert!(r.version.is_some(), "{id}: {}", r.reference);
            assert!(r.license_note.is_some(), "{id}: {}", r.reference);
        }
        let sheet = format!(
            "docs/curriculum/weeks/week-{:02}.md#{}",
            dd_week(&d, id),
            id.to_lowercase()
        );
        assert!(
            dd.resources
                .iter()
                .any(|r| r.kind == ResourceKind::Internal && r.reference == sheet),
            "{id}: the day's own sheet {sheet} is listed"
        );
    }
}

fn dd_week(m: &Manifest, day_id: &str) -> u32 {
    m.days()
        .find(|(_, d)| d.day_id == day_id)
        .map(|(w, _)| w.week_number)
        .expect("the day exists")
}

#[test]
fn the_diff_against_the_seed_touches_only_the_enrichment_fields() {
    let (s, d) = (seed(), draft());
    let report = reconcile(&s, &d).unwrap();

    assert!(report.curriculum_id_matches);
    assert_eq!(report.summary.missing_in_candidate, 0);
    assert_eq!(report.summary.added_in_candidate, 0);
    assert_eq!(
        report.summary.metadata_changes,
        Vec::<String>::new(),
        "no structural or naming change; version and provenance note are excluded by design"
    );
    assert_eq!(report.summary.duplicate_day_ids_original.len(), 0);
    assert_eq!(report.summary.duplicate_day_ids_candidate.len(), 0);
    assert_eq!(report.per_day.len(), 72);

    // Every day gains an artifact criterion, objective criteria, competency links and resources.
    assert_eq!(report.summary.changed, 72);
    assert_eq!(report.summary.unchanged, 0);
    let mut seen: BTreeSet<String> = BTreeSet::new();
    for row in &report.per_day {
        match &row.status {
            DayDiffStatus::Changed { fields } => {
                for f in fields {
                    assert!(
                        is_enrichment_field(f),
                        "{}: '{f}' is not an enrichment field",
                        row.day_id
                    );
                    seen.insert(f.clone());
                }
                for must in ["evidence_artifact", "resources"] {
                    assert!(
                        fields.iter().any(|f| f == must),
                        "{}: expected '{must}' to change",
                        row.day_id
                    );
                }
                for i in 0..3 {
                    for part in ["text", "competency_ids"] {
                        let f = format!("objectives[{i}].{part}");
                        assert!(
                            fields.contains(&f),
                            "{}: expected '{f}' to change",
                            row.day_id
                        );
                    }
                }
            }
            other => panic!("{}: unexpected status {other:?}", row.day_id),
        }
    }
    assert_eq!(seen.len(), 2 + 6, "the eight fields of the enrichment");

    // The diff is a pure function of the two manifests.
    let again = reconcile(&s, &d).unwrap();
    assert_eq!(report.diff_checksum, again.diff_checksum);
    assert_eq!(report.human_readable, again.human_readable);
}

#[test]
fn promotion_needs_a_reconciliation_block_bound_to_this_exact_diff() {
    use ManifestProvenance::*;
    let (s, d) = (seed(), draft());
    let report = reconcile(&s, &d).unwrap();

    // 1. Unreviewed: the draft as it is cannot be promoted.
    assert_eq!(report.binding, ReconciliationBinding::Absent);
    assert!(!report.promotion_allowed);
    assert!(matches!(
        can_promote(&report),
        Err(PromotionBlocked::UnreconciledDifferences { changed: 72, .. })
    ));
    assert!(report.human_readable.contains("promotion: BLOCKED"));
    assert!(matches!(
        check_transition(ProposedSeed, ApprovedCanonical, Some(&report)),
        Err(PromotionBlocked::TransitionNotAllowed { .. })
    ));

    // 2. A candidate whose block carries the checksums of the diff that was reviewed.
    let candidate = reconciled(&report, &d);
    assert!(validate(&candidate).is_valid());
    let r = reconcile(&s, &candidate).unwrap();
    assert_eq!(
        r.diff_checksum, report.diff_checksum,
        "the diff checksum ignores provenance, version and the block"
    );
    assert_eq!(r.binding, ReconciliationBinding::Matched);
    assert!(r.promotion_allowed);
    assert_eq!(can_promote(&r), Ok(()));
    assert_eq!(
        check_transition(ReconciledCandidate, ApprovedCanonical, Some(&r)),
        Ok(())
    );
    // The report still asks for the operator's approval; it does not give it.
    assert!(r.human_readable.contains("APPROVAL REQUEST"));

    // 3. The candidate changes after review (one objective is edited): the block no longer matches.
    let mut edited = candidate.clone();
    edited.weeks[2].days[1].objectives[0]
        .text
        .push_str(" (edited after review)");
    let r = reconcile(&s, &edited).unwrap();
    assert!(matches!(
        r.binding,
        ReconciliationBinding::DiffChecksumMismatch { .. }
    ));
    assert!(!r.promotion_allowed);

    // 4. A block written against some other original is refused as well.
    let mut other_original = s.clone();
    other_original.weeks[0].days[0].objectives[0].text = "Another original".to_string();
    let r = reconcile(&other_original, &candidate).unwrap();
    assert!(!r.promotion_allowed);
    assert_ne!(r.binding, ReconciliationBinding::Matched);

    // 5. The reconciled candidate still plans as non-authoritative until it is promoted.
    let plan = daily_plan(&candidate, 1, 1).unwrap();
    assert_eq!(plan.provenance, ReconciledCandidate);
    assert!(!plan.authoritative);
}
